import request from '../utils/request';

// 登录
export const getLogin = params => {
    return request({
        url: 'login',
        method: 'post',
        data: params,
    });
};

// 修改密码  
export const getChangePassWord = params => {
    return request({
        url: 'user/change-password',
        method: 'post',
        data: params,
    });
};

// 重置密码
export const getRest = id => {
    return request({
        url: `user/reset-password/${id}`,
        method: 'post',
    });
};

// 用户列表
export const getUserList = params => {
    return request({
        url: 'user/list',
        method: 'get',
        params: params
    });
};

// 新增用户
export const getAddUser = params => {
    return request({
        url: 'user/add',
        method: 'post',
        data: params,
    });
};

// 编辑用户
export const getEditUser = params => {
    return request({
        url: 'user/upd',
        method: 'post',
        data: params,
    });
};

// 删除用户
export const getDelUser = id => {
    return request({
        url: `user/del/${id}`,
        method: 'post',
        data: {},
    });
};

